        return False

    try:
        month = int(date[0:2])
        day = int(date[3:5])
        year = int(date[6:10])
    except ValueError:
        return False

    if month < 1 or month > 12:
        return False

    if month in {1, 3, 5, 7, 8, 10, 12}:
        return 1 <= day <= 31
    elif month in {4, 6, 9, 11}:
        return 1 <= day <= 30
    elif month == 2:
        return 1 <= day <= 29

    return False

